'use strict';
const H={};
const p={"action":"valid","unit":"rad"};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 把观测和动作契约写清
Object.assign(s, ((s,p)=>({state:[.1,.2],action:p.action==='valid'?[.2,.3]:[.2],requiredDof:2,unit:p.unit}))(s, p));
// 检查维度和有限值
Object.assign(s, ((s,p)=>({shapeValid:s.action.length===s.requiredDof,finite:s.action.every(Number.isFinite)}))(s, p));
// 把单位校验独立列出
Object.assign(s, ((s,p)=>({unitValid:s.unit==='rad'}))(s, p));
// 报告输入是否允许进入训练
Object.assign(s, ((s,p)=>({accepted:s.shapeValid&&s.finite&&s.unitValid}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"delay":0.05,"tolerance":0.05};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 各传感器保留原时间戳
Object.assign(s, ((s,p)=>({stateTimes:[0,.1,.2],cameraTimes:[p.delay,.1+p.delay,.2+p.delay]}))(s, p));
// 对每个状态选择最近相机帧
Object.assign(s, ((s,p)=>({matches:s.stateTimes.map(t=>{const ds=s.cameraTimes.map(c=>Math.abs(c-t));let i=0;for(let j=1;j<ds.length;j++)if(ds[j]<ds[i]-1e-9)i=j;return {state:t,camera:s.cameraTimes[i],index:i,error:ds[i]};})}))(s, p));
// 检查时间容差与未来帧
Object.assign(s, ((s,p)=>({valid:s.matches.map(m=>m.error<=p.tolerance+1e-9),future:s.matches.map(m=>m.camera>m.state+1e-9)}))(s, p));
// 分别报告可配对和在线可用
Object.assign(s, ((s,p)=>({acceptedCount:s.valid.filter(Boolean).length,causalCount:s.matches.filter((m,i)=>s.valid[i]&&!s.future[i]).length}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"split":"episode"};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 保留回合和时间身份
Object.assign(s, ((s,p)=>({episodes:['A','A','B','B'],frameIndex:[0,1,0,1]}))(s, p));
// 先划分再拟合统计量
Object.assign(s, ((s,p)=>({train:p.split==='episode'?[0,1]:[0,2],validation:p.split==='episode'?[2,3]:[1,3]}))(s, p));
// 检查回合是否跨边界
Object.assign(s, ((s,p)=>({overlap:[...new Set(s.train.map(i=>s.episodes[i]))].filter(e=>s.validation.some(i=>s.episodes[i]===e))}))(s, p));
// 保留进一步独立性的要求
Object.assign(s, ((s,p)=>({episodeIndependent:s.overlap.length===0,trainingFrames:s.train.length,validationFrames:s.validation.length}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={mean:xs=>xs.reduce((a,b)=>a+b,0)/xs.length};
const p={"validation":8,"fit":"train"};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先固定训练和保留样本
Object.assign(s, ((s,p)=>({train:[0,2,4],validation:p.validation}))(s, p));
// 只从允许的数据拟合中心和尺度
Object.assign(s, ((s,p)=>{const fit=p.fit==='train'?s.train:s.train.concat([s.validation]),center=H.mean(fit),scale=Math.sqrt(H.mean(fit.map(x=>(x-center)**2)));return {center,scale};})(s, p));
// 同一变换应用到保留样本
Object.assign(s, ((s,p)=>({normalized:(s.validation-s.center)/s.scale}))(s, p));
// 用逆变换核对单位恢复
Object.assign(s, ((s,p)=>({recovered:s.normalized*s.scale+s.center,leaked:p.fit==='all'}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={mean:xs=>xs.reduce((a,b)=>a+b,0)/xs.length};
const p={"weight":1,"rate":0.1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 声明训练样本和回合级保留集
Object.assign(s, ((s,p)=>({observations:[0,1,2],actions:[0,2,4],heldOut:[3,6]}))(s, p));
// 拟合一个线性行为策略
Object.assign(s, ((s,p)=>({errors:s.observations.map((o,i)=>p.weight*o-s.actions[i])}))(s, p));
// 只用训练数据更新
Object.assign(s, ((s,p)=>({gradient:H.mean(s.errors.map((e,i)=>e*s.observations[i])),trainingLoss:H.mean(s.errors.map(e=>e*e))/2}))(s, p));
// 更新后独立评价一次
Object.assign(s, ((s,p)=>({weight:p.weight-p.rate*s.gradient,heldOutError:(p.weight-p.rate*s.gradient)*s.heldOut[0]-s.heldOut[1]}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"execute":2,"latency":60};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 区分预测长度和执行长度
Object.assign(s, ((s,p)=>({chunk:[.1,.2,.3,.4],controlPeriod:20}))(s, p));
// 每次只提交前k个动作
Object.assign(s, ((s,p)=>({executed:s.chunk.slice(0,p.execute),coverage:p.execute*s.controlPeriod}))(s, p));
// 比较覆盖时间和计算延迟
Object.assign(s, ((s,p)=>({gap:Math.max(0,p.latency-s.coverage),slack:s.coverage-p.latency}))(s, p));
// 陈述时序与任务表现的不同
Object.assign(s, ((s,p)=>({noGap:s.gap===0,feedbackInterval:s.coverage}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"command":1,"current":0,"fresh":"yes"};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先检查动作契约和当前状态
Object.assign(s, ((s,p)=>({command:p.command,current:p.current,fresh:p.fresh==='yes'}))(s, p));
// 分开检查位置和变化率
Object.assign(s, ((s,p)=>({positionValid:s.command>=-1&&s.command<=1,delta:s.command-s.current}))(s, p));
// 决定是否允许提交
Object.assign(s, ((s,p)=>({allowed:s.fresh&&s.positionValid&&Math.abs(s.delta)<=.2+1e-9}))(s, p));
// 保留失败原因
Object.assign(s, ((s,p)=>({submitted:false,reason:!s.fresh?'观测过期':!s.positionValid?'位置超界':Math.abs(s.delta)>.2+1e-9?'单周期变化过大':'通过教学检查，未实际提交'}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={wilson:(success,n)=>{const z=1.96,p=success/n,d=1+z*z/n,m=(p+z*z/(2*n))/d,h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return [m-h,m+h];}};
const p={"successes":14,"baseline":10};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先固定回合级任务成功定义
Object.assign(s, ((s,p)=>({episodes:20,successes:p.successes,baseline:p.baseline}))(s, p));
// 比较相同条件的成功率
Object.assign(s, ((s,p)=>({rate:s.successes/s.episodes,baselineRate:s.baseline/s.episodes}))(s, p));
// 给成功率附上不确定性
Object.assign(s, ((s,p)=>({interval:H.wilson(s.successes,s.episodes),baselineInterval:H.wilson(s.baseline,s.episodes)}))(s, p));
// 按预先约定报告效果差异
Object.assign(s, ((s,p)=>({difference:s.rate-s.baselineRate,percentagePoints:100*(s.rate-s.baselineRate)}))(s, p));
console.log(JSON.stringify(s,null,2));
